template:
% 参数由系统自动注入：\def\radius{3} \def\opdist{6} \def\secantfrac{0.55} \def\secondfrac{0.85} \def\showtangent{1} \def\showsecant{1} \def\showradius{0} \def\showsecond{0} \def\showsimilar{0} \def\showcenter{1} \def\labelp{P} \def\labelt{T} \def\labela{A} \def\labelb{B} \def\labelc{C} \def\labeld{D}
% 视觉归一化：把图形最宽跨度（圆最左端到外点 P）缩放到 6cm，保证图形视觉大小稳定。
\pgfmathsetmacro{\figscale}{6 / (\radius + \opdist)}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
% P 放在正右方；切点 T 在上方（∠TOP = arccos(radius/opdist)），割线一律向下方偏，避免与切线重叠
\pgfmathsetmacro{\tha}{acos(\radius/\opdist)}
\pgfmathsetmacro{\Tx}{\radius*cos(\tha)}
\pgfmathsetmacro{\Ty}{\radius*sin(\tha)}
% ∠OPT 是从 P 看圆的半张角，割线与 PO 的夹角小于它才能割到圆，故用比例参数乘上它
\pgfmathsetmacro{\maxang}{asin(\radius/\opdist)}
\pgfmathsetmacro{\sdirone}{180 + \secantfrac*\maxang}
\pgfmathsetmacro{\sdirtwo}{180 + \secondfrac*\maxang}
% 过 P 沿方向 u 的直线与圆的交点：解 |P + t*u|^2 = radius^2，P 在圆外故两根同正，小根为近交点
\pgfmathsetmacro{\uax}{cos(\sdirone)}
\pgfmathsetmacro{\uay}{sin(\sdirone)}
\pgfmathsetmacro{\pua}{\opdist*\uax}
\pgfmathsetmacro{\hlena}{sqrt(\pua*\pua - \opdist*\opdist + \radius*\radius)}
\pgfmathsetmacro{\Ax}{\opdist + (-\pua - \hlena)*\uax}
\pgfmathsetmacro{\Ay}{(-\pua - \hlena)*\uay}
\pgfmathsetmacro{\Bx}{\opdist + (-\pua + \hlena)*\uax}
\pgfmathsetmacro{\By}{(-\pua + \hlena)*\uay}
\pgfmathsetmacro{\ubx}{cos(\sdirtwo)}
\pgfmathsetmacro{\uby}{sin(\sdirtwo)}
\pgfmathsetmacro{\pub}{\opdist*\ubx}
\pgfmathsetmacro{\hlenb}{sqrt(\pub*\pub - \opdist*\opdist + \radius*\radius)}
\pgfmathsetmacro{\Cx}{\opdist + (-\pub - \hlenb)*\ubx}
\pgfmathsetmacro{\Cy}{(-\pub - \hlenb)*\uby}
\pgfmathsetmacro{\Dx}{\opdist + (-\pub + \hlenb)*\ubx}
\pgfmathsetmacro{\Dy}{(-\pub + \hlenb)*\uby}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \draw[thick] (0,0) circle [radius=\radius];
  % 切线 PT：从 P 到切点 T，并沿切向略微延长以呈现「线」的形态
  \ifnum\showtangent>0
    \draw[thick] ({\opdist},0) -- ({\Tx + 0.2*\radius*cos(\tha+90)},{\Ty + 0.2*\radius*sin(\tha+90)});
    \fill ({\Tx},{\Ty}) circle [radius=\dotr pt];
    \node[above right] at ({\Tx},{\Ty}) {$\labelt$};
  \fi
  % 切点半径 OT 与直角记号
  \ifnum\showradius>0
    \draw[thick] (0,0) -- ({\Tx},{\Ty});
    \pgfmathsetmacro{\rmsz}{min(0.28/\figscale, \radius*0.22)}
    \pgfmathsetmacro{\rox}{-cos(\tha)}
    \pgfmathsetmacro{\roy}{-sin(\tha)}
    \pgfmathsetmacro{\rpx}{cos(\tha-90)}
    \pgfmathsetmacro{\rpy}{sin(\tha-90)}
    \draw[thick] ({\Tx + \rmsz*\rox},{\Ty + \rmsz*\roy}) -- ({\Tx + \rmsz*\rox + \rmsz*\rpx},{\Ty + \rmsz*\roy + \rmsz*\rpy}) -- ({\Tx + \rmsz*\rpx},{\Ty + \rmsz*\rpy});
  \fi
  % 割线 PAB：P 到远交点 B 的线段，A 在中间
  \ifnum\showsecant>0
    \draw[thick] ({\opdist},0) -- ({\Bx},{\By});
    \fill ({\Ax},{\Ay}) circle [radius=\dotr pt];
    \node[above right] at ({\Ax},{\Ay}) {$\labela$};
    \fill ({\Bx},{\By}) circle [radius=\dotr pt];
    \node[left] at ({\Bx},{\By}) {$\labelb$};
  \fi
  % 第二条割线 PCD（割线定理）
  \ifnum\showsecond>0
    \draw[thick] ({\opdist},0) -- ({\Dx},{\Dy});
    \fill ({\Cx},{\Cy}) circle [radius=\dotr pt];
    \node[below right] at ({\Cx},{\Cy}) {$\labelc$};
    \fill ({\Dx},{\Dy}) circle [radius=\dotr pt];
    \node[below left] at ({\Dx},{\Dy}) {$\labeld$};
  \fi
  % 相似三角形辅助线：△PTA ∽ △PBT
  \ifnum\showsimilar>0
    \draw[thick] ({\Tx},{\Ty}) -- ({\Ax},{\Ay});
    \draw[thick] ({\Tx},{\Ty}) -- ({\Bx},{\By});
  \fi
  \ifnum\showcenter>0
    \fill (0,0) circle [radius=\dotr pt];
    \node[above left] at (0,0) {$O$};
  \fi
  \fill ({\opdist},0) circle [radius=\dotr pt];
  \node[right] at ({\opdist},0) {$\labelp$};
\end{tikzpicture}
